def second_largest(xs):
    ordered = sorted(xs)
    if not ordered:
        return None
    copies = ordered.count(ordered[-1])     # how many times the largest value appears
    if copies == len(ordered):
        return None
    return ordered[-copies - 1]


def without(xs, value):
    result = xs.copy()
    if value in result:
        result.remove(value)
    return result


def rotate(xs, k):
    if not xs:
        return []
    k %= len(xs)
    return xs[-k:] + xs[:-k] if k else xs[:]
